pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor, uint256 t) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 100 ether);
        t = bound(t, 1, type(uint256).max - 1);
        vm.assume(t > block.timestamp);

        vm.deal(actor, amount);
        vm.warp(t);
        vm.prank(actor);

        bool ok;
        try c.fallback{value: amount}() { ok = true; } catch { ok = false; }

        // General rule: the call succeeds exactly when exactly 10 ether is sent
        // (timestamp was strictly advanced). The mutant accepts only 1 ether.
        assertTrue(ok == (amount == 10 ether));
    }
}

