import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(address actor, uint256 amount, uint256 timeJump) public {
        vm.assume(amount == 10 ether);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(timeJump > 0 && timeJump < 1e9);

        vm.warp(block.timestamp + timeJump);
        vm.roll(block.number + 1);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: amount}("");
        assertTrue(ok1);

        // second call in the SAME block: reference reverts, mutant accepts
        vm.deal(actor, amount);
        bool ok2;
        vm.prank(actor);
        (bool s, ) = address(c).call{value: amount}("");
        ok2 = s;
        (s, );

        assertTrue(!ok2, "same-block repeat call must be rejected");
    }
}

