import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 t1, uint64 delta) public {
        // first call at some timestamp t1 (admissible: t1 > 0)
        vm.assume(t1 > 0);
        // second call strictly later
        uint64 t2 = t1 + (delta % 1_000_000 + 1);
        address actor = address(0xA11CE);

        vm.deal(actor, 20 ether);

        // first call at t1
        vm.warp(t1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // second call at a strictly later timestamp: a correct contract accepts it
        vm.warp(t2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok2, "a call at a later timestamp must succeed after a successful call");
    }
}

