pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 t1, uint64 t2) public {
        // Admissible domain: two strictly increasing positive timestamps.
        t1 = uint64(bound(t1, 1, type(uint64).max - 1));
        vm.assume(t2 > t1);

        address actor = address(0xABCD);
        vm.deal(actor, 10 ether);

        // First call at t1 (t1 > initial pastBlockTime of 0).
        vm.warp(t1);
        vm.prank(actor);
        bool ok1;
        try c.fallback{value: 10 ether}() { ok1 = true; } catch { ok1 = false; }

        // Second call at a later timestamp t2 > t1 > pastBlockTime.
        vm.warp(t2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok2;
        try c.fallback{value: 10 ether}() { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && ok2 && c.pastBlockTime() == t2);
    }
}

