contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNo, address actor) public {
        vm.assume(blockNo > 0);
        vm.assume(actor != address(0));
        vm.assume(uint256(uint160(actor)) > 1);

        // fund the contract so a payout is observable beyond the deposited 10 ether
        vm.deal(address(c), 50 ether);

        vm.warp(blockNo * 100 + 1); // fresh, strictly increasing timestamp
        vm.roll(blockNo);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // GENERAL RULE: a call made at a block with block.number % 15 == 0
        // always drains the whole contract balance to the caller.
        assertTrue(
            blockNo % 15 != 0 || address(c).balance == 0,
            "payout must occur exactly when block.number % 15 == 0"
        );
    }
}

